  `qty_received_base` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT 'Qty diterima kali ini (base uom)',
  `unit_price` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT 'Harga per purchase uom',
