/*Table structure for table `investor_transactions` */

DROP TABLE IF EXISTS `investor_transactions`;

CREATE TABLE `investor_transactions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_code` varchar(50) NOT NULL,
  `investor_id` int(11) NOT NULL,
  `transaction_date` date NOT NULL,
  `type` enum('INJECTION','WITHDRAWAL','DIVIDEND') NOT NULL COMMENT 'INJECTION=Suntikan, WITHDRAWAL=Tarik Dana, DIVIDEND=Bagi Hasil',
  `category` enum('DEBT','EQUITY') NOT NULL COMMENT 'DEBT=Hutang Sementara, EQUITY=Modal Permanen',
  `amount` decimal(18,2) NOT NULL DEFAULT 0.00,
  `payment_method` enum('CASH','BANK') DEFAULT 'BANK',
  `description` text DEFAULT NULL,
  `journal_id` int(11) DEFAULT NULL,
  `status` enum('POSTED','VOID') DEFAULT 'POSTED',
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inv_trx_code` (`transaction_code`),
  KEY `idx_investor_id` (`investor_id`),
  CONSTRAINT `fk_inv_trx_investor` FOREIGN KEY (`investor_id`) REFERENCES `investors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `investor_transactions` */

/*Table structure for table `investors` */

DROP TABLE IF EXISTS `investors`;

CREATE TABLE `investors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `equity_percentage` decimal(5,2) DEFAULT 0.00 COMMENT 'Persentase Kepemilikan (%)',
  `status` enum('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `investors` */

/*Table structure for table `journal_items` */

DROP TABLE IF EXISTS `journal_items`;

CREATE TABLE `journal_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `journal_id` int(11) NOT NULL,
  `account_id` int(11) NOT NULL,
  `line_description` varchar(255) DEFAULT NULL,
  `debit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `credit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_journal_id` (`journal_id`),
  KEY `idx_account_id` (`account_id`),
  CONSTRAINT `fk_journal_items_account` FOREIGN KEY (`account_id`) REFERENCES `chart_of_accounts` (`id`),
  CONSTRAINT `fk_journal_items_journal` FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1494 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `journal_items` */


/*Table structure for table `journals` */

DROP TABLE IF EXISTS `journals`;

CREATE TABLE `journals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `journal_number` varchar(50) NOT NULL,
  `transaction_date` date NOT NULL,
  `description` text DEFAULT NULL,
  `reference_number` varchar(100) DEFAULT NULL,
  `source_module` varchar(50) DEFAULT NULL,
  `source_id` int(11) DEFAULT NULL,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` enum('DRAFT','POSTED','VOID') NOT NULL DEFAULT 'POSTED',
  `void_reason` text DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `voided_by` varchar(100) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_journal_number` (`journal_number`),
  KEY `idx_transaction_date` (`transaction_date`),
  KEY `idx_source_module` (`source_module`),
  KEY `idx_source_id` (`source_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=747 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `journals` */


/*Table structure for table `landing_catalogs` */

DROP TABLE IF EXISTS `landing_catalogs`;

CREATE TABLE `landing_catalogs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_name` varchar(255) NOT NULL,
  `category` varchar(100) NOT NULL,
  `product_image` varchar(255) DEFAULT NULL,
  `price` int(11) NOT NULL,
  `discount_price` int(11) DEFAULT 0,
  `specs` varchar(255) DEFAULT NULL,
  `badge_text` varchar(50) DEFAULT NULL,
  `icon_class` varchar(100) DEFAULT 'ph-motorcycle',
  `shopee_link` text DEFAULT NULL,
  `wa_link` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `landing_catalogs` */

/*Table structure for table `leave_requests` */

DROP TABLE IF EXISTS `leave_requests`;

CREATE TABLE `leave_requests` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` varchar(20) NOT NULL,
  `leave_type` varchar(50) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `duration` int(3) NOT NULL,
  `reason` text NOT NULL,
  `attachment` varchar(255) DEFAULT NULL,
  `status` enum('Pending','Approved','Rejected') DEFAULT 'Pending',
  `reviewed_by` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `leave_requests` */

/*Table structure for table `offline_sale_items` */

DROP TABLE IF EXISTS `offline_sale_items`;

CREATE TABLE `offline_sale_items` (
