/*Table structure for table `production_logs` */

DROP TABLE IF EXISTS `production_logs`;

CREATE TABLE `production_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sku` varchar(100) NOT NULL,
  `spk_number` varchar(50) NOT NULL,
  `bom_id` int(10) unsigned DEFAULT NULL,
  `operation_id` int(10) unsigned DEFAULT NULL,
  `section_id` int(10) unsigned DEFAULT NULL,
  `qty_produced` int(11) NOT NULL,
  `qty_reject` decimal(15,2) DEFAULT 0.00,
  `operation_name` varchar(100) DEFAULT NULL,
  `is_final_step` tinyint(1) DEFAULT 0,
  `status` enum('Pending','Approved','Rejected') DEFAULT 'Approved',
  `approved_by` varchar(100) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `wage_per_piece` decimal(15,2) DEFAULT 0.00,
  `total_wage` decimal(15,2) DEFAULT 0.00,
  `production_date` datetime DEFAULT current_timestamp(),
  `notes` text DEFAULT NULL,
  `extra_materials` text DEFAULT NULL,
  `employee_id` varchar(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `production_logs` */


/*Table structure for table `production_material_usages` */

DROP TABLE IF EXISTS `production_material_usages`;

CREATE TABLE `production_material_usages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
