/*Table structure for table `purchase_order_items` */

DROP TABLE IF EXISTS `purchase_order_items`;

CREATE TABLE `purchase_order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `rm_sku` varchar(50) NOT NULL,
  `purchase_uom` varchar(50) DEFAULT NULL,
  `base_uom` varchar(50) DEFAULT NULL,
  `conversion_factor` decimal(18,4) NOT NULL DEFAULT 1.0000,
  `qty` decimal(10,2) NOT NULL,
  `qty_base` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `qty_received` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT 'Total qty sudah diterima (base uom)',
  `is_fully_received` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = semua qty sudah diterima',
  `uom_note` varchar(255) DEFAULT NULL COMMENT 'Catatan konversi untuk operator',
  `unit_price` decimal(15,2) NOT NULL,
  `unit_price_base` decimal(18,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(15,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `po_id` (`po_id`),
  CONSTRAINT `purchase_order_items_ibfk_1` FOREIGN KEY (`po_id`) REFERENCES `purchase_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `purchase_order_items` */


/*Table structure for table `purchase_order_payments` */

DROP TABLE IF EXISTS `purchase_order_payments`;

CREATE TABLE `purchase_order_payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `payment_date` date NOT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `finance_account_code` varchar(50) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `reference_number` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `po_id` (`po_id`),
  CONSTRAINT `purchase_order_payments_ibfk_1` FOREIGN KEY (`po_id`) REFERENCES `purchase_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `purchase_order_payments` */


/*Table structure for table `purchase_orders` */

DROP TABLE IF EXISTS `purchase_orders`;

CREATE TABLE `purchase_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_number` varchar(50) NOT NULL,
  `supplier_id` int(11) NOT NULL,
  `po_date` date NOT NULL,
  `payment_term` varchar(150) DEFAULT 'Bank Transfer (IDR)',
  `status` enum('DRAFT','ORDERED','RECEIVED') DEFAULT 'ORDERED',
  `payment_status` enum('UNPAID','PARTIAL','PAID') DEFAULT 'UNPAID',
  `receipt_status` enum('PENDING','PARTIAL','FULLY_RECEIVED') NOT NULL DEFAULT 'PENDING' COMMENT 'Status penerimaan fisik barang',
  `received_at` datetime DEFAULT NULL,
  `received_by` varchar(100) DEFAULT NULL,
  `subtotal` decimal(15,2) DEFAULT 0.00,
  `tax_amount` decimal(15,2) DEFAULT 0.00,
  `shipping_cost` decimal(15,2) DEFAULT 0.00,
  `total_amount` decimal(15,2) DEFAULT 0.00,
  `paid_amount` decimal(15,2) DEFAULT 0.00,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `supplier_id` (`supplier_id`),
  CONSTRAINT `purchase_orders_ibfk_1` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `purchase_orders` */


/*Table structure for table `raw_materials` */

DROP TABLE IF EXISTS `raw_materials`;

CREATE TABLE `raw_materials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sku_material` varchar(100) NOT NULL,
  `material_name` varchar(255) NOT NULL,
  `base_uom` varchar(20) DEFAULT NULL,
