/*Table structure for table `work_orders` */

DROP TABLE IF EXISTS `work_orders`;

CREATE TABLE `work_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `so_id` int(11) DEFAULT NULL,
  `spk_number` varchar(50) NOT NULL,
  `bom_id` int(11) NOT NULL,
  `planned_qty` int(11) NOT NULL,
  `completed_qty` decimal(15,2) DEFAULT 0.00,
  `production_notes` varchar(255) DEFAULT NULL,
  `actual_material_cost` decimal(18,2) DEFAULT 0.00,
  `actual_labor_cost` decimal(18,2) DEFAULT 0.00,
  `actual_overhead_cost` decimal(18,2) DEFAULT 0.00,
  `actual_total_cost` decimal(18,2) DEFAULT 0.00,
  `material_cost` decimal(15,2) DEFAULT 0.00,
  `labor_cost` decimal(15,2) DEFAULT 0.00,
  `overhead_cost` decimal(15,2) DEFAULT 0.00,
  `actual_hpp` decimal(15,2) DEFAULT 0.00,
  `status` enum('DRAFT','IN_PROGRESS','COMPLETED') DEFAULT 'DRAFT',
  `source` varchar(20) DEFAULT 'MANUAL',
  `start_date` date DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `completed_date` date DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `work_orders` */


/*Table structure for table `work_shifts` */

DROP TABLE IF EXISTS `work_shifts`;

CREATE TABLE `work_shifts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `shift_name` varchar(100) NOT NULL,
  `shift_type` enum('Reguler','Fleksibel') DEFAULT 'Reguler',
  `time_in` time DEFAULT NULL,
  `scan_in_before` int(11) DEFAULT 60,
  `scan_in_after` int(11) DEFAULT 120,
  `time_out` time DEFAULT NULL,
  `scan_out_before` int(11) DEFAULT 30,
  `scan_out_after` int(11) DEFAULT 240,
  `break_out` time DEFAULT NULL,
  `break_in` time DEFAULT NULL,
  `late_tolerance` int(11) DEFAULT 15,
  `late_penalty_rate` decimal(15,2) DEFAULT 0.00,
  `early_leave_tolerance` int(11) DEFAULT 0,
  `half_day_duration` int(11) DEFAULT 240,
  `full_day_duration` int(11) DEFAULT 480,
  `min_overtime` int(11) DEFAULT 60,
  `max_overtime` int(11) DEFAULT 240,
  `overtime_deduction` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `work_shifts` */


/*Table structure for table `v_account_balances` */

DROP TABLE IF EXISTS `v_account_balances`;

/*!50001 DROP VIEW IF EXISTS `v_account_balances` */;
/*!50001 DROP TABLE IF EXISTS `v_account_balances` */;

/*!50001 CREATE TABLE  `v_account_balances`(
 `id` int(11) ,
 `account_code` varchar(20) ,
 `account_name` varchar(150) ,
 `account_type` enum('ASET','LIABILITI','EKUITI','PENDAPATAN','PERBELANJAAN') ,
 `normal_balance` enum('DEBIT','KREDIT') ,
 `is_contra` tinyint(1) ,
 `is_active` tinyint(1) ,
 `calculated_balance` decimal(38,2) 
)*/;

/*View structure for view v_account_balances */

/*!50001 DROP TABLE IF EXISTS `v_account_balances` */;
/*!50001 DROP VIEW IF EXISTS `v_account_balances` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`uwjqdfka_test`@`%` SQL SECURITY DEFINER VIEW `v_account_balances` AS select `coa`.`id` AS `id`,`coa`.`account_code` AS `account_code`,`coa`.`account_name` AS `account_name`,`coa`.`account_type` AS `account_type`,`coa`.`normal_balance` AS `normal_balance`,`coa`.`is_contra` AS `is_contra`,`coa`.`is_active` AS `is_active`,coalesce(sum(case when `coa`.`normal_balance` = 'DEBIT' then `ji`.`debit` - `ji`.`credit` when `coa`.`normal_balance` = 'KREDIT' then `ji`.`credit` - `ji`.`debit` else 0 end),0) AS `calculated_balance` from ((`chart_of_accounts` `coa` left join `journal_items` `ji` on(`ji`.`account_id` = `coa`.`id`)) left join `journals` `j` on(`j`.`id` = `ji`.`journal_id` and `j`.`status` = 'POSTED')) group by `coa`.`id`,`coa`.`account_code`,`coa`.`account_name`,`coa`.`account_type`,`coa`.`normal_balance`,`coa`.`is_contra`,`coa`.`is_active` */;

